window.PMM_NAHJ_TRANSCRIPT_ACCEPT({"group":"sermons","number":183,"source":"خطبه 183.docx","mode":"explicit-parts","parts":["خطبه ۱۸۳\nبخش اول\nمتن:\nمن خطبة له (علیه السلام) في قدرة اللّه و في فضل القرآن و في الوصية بالتقوى:\nالله تعالى:\nالْحَمْدُ لِلَّهِ الْمَعْرُوفِ مِنْ غَيْرِ رُؤْيَةٍ وَ الْخَالِقِ مِنْ غَيْرِ مَنْصَبَةٍ؛ خَلَقَ الْخَلَائِقَ بِقُدْرَتِهِ وَ اسْتَعْبَدَ الْأَرْبَابَ بِعِزَّتِهِ وَ سَادَ الْعُظَمَاءَ بِجُودِهِ؛ وَ هُوَ الَّذِي أَسْكَنَ الدُّنْيَا خَلْقَهُ وَ بَعَثَ إِلَى الْجِنِّ وَ الْإِنْسِ رُسُلَهُ، لِيَكْشِفُوا لَهُمْ عَنْ غِطَائِهَا وَ لِيُحَذِّرُوهُمْ مِنْ ضَرَّائِهَا وَ لِيَضْرِبُوا لَهُمْ أَمْثَالَهَا وَ لِيُبَصِّرُوهُمْ عُيُوبَهَا، وَ لِيَهْجُمُوا عَلَيْهِمْ بِمُعْتَبَرٍ مِنْ تَصَرُّفِ مَصَاحِّهَا وَ أَسْقَامِهَا وَ حَلَالِهَا وَ حَرَامِهَا، وَ مَا أَعَدَّ اللَّهُ لِلْمُطِيعِينَ مِنْهُمْ وَ الْعُصَاةِ مِنْ جَنَّةٍ وَ نَارٍ وَ كَرَامَةٍ وَ هَوَانٍ. أَحْمَدُهُ إِلَى نَفْسِهِ كَمَا اسْتَحْمَدَ إِلَى خَلْقِهِ، وَ جَعَلَ لِكُلِّ شَيْءٍ قَدْراً وَ لِكُلِّ قَدْرٍ أَجَلًا وَ لِكُلِّ أَجَلٍ كِتَاباً.\nمِنها: فَالْقُرْآنُ آمِرٌ زَاجِرٌ وَ صَامِتٌ نَاطِقٌ، حُجَّةُ اللَّهِ عَلَى خَلْقِهِ، أَخَذَ عَلَيْهِ مِيثَاقَهُمْ وَ ارْتَهَنَ عَلَيْهِمْ أَنْفُسَهُمْ؛ أَتَمَّ نُورَهُ وَ أَكْمَلَ بِهِ دِينَهُ وَ قَبَضَ نَبِيَّهُ (صلی الله علیه وآله) وَ قَدْ فَرَغَ إِلَى الْخَلْقِ مِنْ أَحْكَامِ الْهُدَى بِهِ؛ فَعَظِّمُوا مِنْهُ سُبْحَانَهُ مَا عَظَّمَ مِنْ نَفْسِهِ، فَإِنَّهُ لَمْ يُخْفِ عَنْكُمْ شَيْئاً مِنْ دِينِهِ وَ لَمْ يَتْرُكْ شَيْئاً رَضِيَهُ أَوْ كَرِهَهُ إِلَّا وَ جَعَلَ لَهُ عَلَماً بَادِياً وَ آيَةً مُحْكَمَةً تَزْجُرُ عَنْهُ أَوْ تَدْعُو إِلَيْهِ؛ فَرِضَاهُ فِيمَا بَقِيَ وَاحِدٌ وَ سَخَطُهُ فِيمَا بَقِيَ وَاحِدٌ\nترجمه:\nستايش مخصوص خداوندى است که بدون اينکه ديده شود شناخته شده، و بى هيچ زحمت و مشقّتى (جهان را) آفريده است. با قدرت خويش مخلوقات را آفريد و با عزّتش گردنکشان را تسليم خود ساخت و با جود و سخايش بر همه بزرگان برترى جُست.\nاو کسى است که خلق خود را در دنيا سکونت داد و رسولانش را به سوى جنّ و انس مبعوث ساخت، تا پرده از چهره دنيا براى آنها برگيرند و آنان را از زيانهايش بر حذر دارند، براى آنها (از بى وفايى دنيا) مَثَلها زنند و عيوب دنياپرستى را به ايشان نشان دهند همچنين با بيانات قوى و کوبنده، آنچه را که مايه عبرت است از تندرستى ها و بيماريها، که يکى بعد از ديگرى ظاهر مى شود، براى آنها بيان کنند. و نيز حلالها و حرامهاى اين دنيا و آنچه را خداوند (در سراى ديگر) براى مطيعان و عاصيان از بهشت و دوزخ و احترام و تحقير فراهم ساخته به آنان گوشزد کنند.\nاو را آن گونه ستايش مى کنم که از بندگانش خواسته است. او براى هر چيز اندازه اى قرار داده و براى هر اندازه اى سرآمدى و براى هر سرآمدى حساب دقيقى تعيين کرده است.\nقرآن امرکننده و بازدارنده است، خاموش است و گويا، و حجت خداست بر خلق. خداوند پيمان عمل به آن را از بندگانش گرفته و آنان را در گرو دستورات قرآن قرار داده است. نور خدا را (در ميان بندگان به وسيله آن) کامل ساخت و دين و آيينش را با آن به حدّ کمال رساند. پيامبرش(صلى الله عليه وآله) را در حالى از اين جهان برد که احکام هدايتگر قرآن را به خلق، رسانده بود.\nحال که چنين است خدا را آن گونه بزرگ بشماريد و توصيف کنيد که خود (در قرآن) بيان کرده، خداوند چيزى از دينش را بر شما پنهان ننموده و هيچ مطلبى را که سبب رضا يا ناخشنوديش باشد وانگذاشته است جز اينکه (در قرآن) نشانه اى آشکار و آيه اى محکم و روشن براى آن قرار داده که از آن باز مى دارد يا به سوى آن دعوت مى کند. (بازداشتن از معاصى و دعوت به سوى اطاعت) رضا و خشم او در گذشته و حال يکسان است. (و اين احکام مخصوص به گروه خاصّى نيست)\nتفسیر:\nبیان توحیدی\nابن ابی‌الحدید در ذیل این خطبه می‌گوید: «این خطبه از بلیغ‌ترین کلام‌های حضرت امیرالمؤمنین است. اگر می‌خواهید ارزش و وزانت کلام حضرت را دریابید، باید سخنان ایشان را با کلمات دیگر ادیبان مقایسه کنید.» او برای این منظور، نمونه‌های متعددی از سخنان بزرگان فصیح عرب می‌آورد و با مقایسهٔ آن‌ها با کلام حضرت نشان می‌دهد که سخنان امیرالمؤمنین چه عظمت و شکوهی دارد؛ هم از جهت ظاهریِ کلام، چینش واژه‌ها و ساختار سخن، و هم از نظر محتوا.\nاینکه انسان متونی را ببیند و آن‌ها را توصیف کند، کجا؛ و اینکه ظریف‌ترین مباحث توحیدی و معاد را با زبانی فصیح و بلیغ بیان کند، کجا؟ این دو اصلاً با یکدیگر قابل‌مقایسه نیستند.\nابن ابی‌الحدید در پایان می‌گوید: «اگر کسی ادعا کند که معلوم نیست کلمات نهج‌البلاغه از سوی علی علیه‌السلام باشد و شاید ساخته‌وپرداختهٔ خود شیعیان باشد که آن را به نام او نوشته‌اند تا سخنانشان نفوذ و اعتبار بیشتری پیدا کند، باید در پاسخ گفت: هرگز چنین سخنی نگویید. من که عمر خود را در راه فصاحت و بلاغت گذرانده‌ام، تمام اشعار را خوانده‌ام و با اسلوب و روش همهٔ فصیحان آشنایی دارم، می‌دانم که نهج‌البلاغه کتابی است که جز از علی نمی‌تواند صادرالبلاغه کتابی است که جز از علی نمی‌تواند صادر به‌اندازه‌ای است که هیچ‌کس نمی‌تواند شبیه آن را بیاورد؛ و این، بهترین دلیل است که این کلمات جعلی و تحریف‌شده نیستند و از خود حضرت صادر شده‌اند.\nالْحَمْدُ لِلَّهِ الْمَعْرُوفِ مِنْ غَیرِ رُؤْیةٍ\nحمد و ستایش، مخصوص خدایی است که بدون دیده‌شدن شناخته شده است.\nما برای خرید وسیله‌ای معمولاً باید پیش از خرید، آن را ببینیم یا دست‌کم تصویرش را مشاهده کنیم؛ اما ما به خدایی دل بسته‌ایم و بندهٔ او شده‌ایم، بی‌آنکه قابل‌رؤیت باشد.\nخداوند جسم ندارد و ازاین‌رو دیده نمی‌شود؛ اما ما او را با فطرت و روح خود درک می‌کنیم. دیده‌نشدن به معنای نبودن نیست.\nوَالْخَالِقِ مِنْ غَیرِ مَنْصَبَةٍ\nحمد و ستایش، مخصوص خدایی است که عالم را بدون زحمت و رنج آفرید.\nبرای خداوند، آفرینش موجود بزرگ و کوچک تفاوتی ندارد؛ چه مورچه‌ای را بیافریند و چه کوه دماوند را. ارادهٔ او برای آفرینش هر چیزی کافی است و آن چیز بدون هیچ زحمت و رنجی کامل می‌شود؛ همان‌گونه که می‌فرماید: «کُنْ فَیَکُونُ».\nخَلَقَ الْخَلَائِقَ بِقُدْرَتِهِ\nمخلوقات را باقدرت بی‌نهایت خود آفرید.\nقدرت خداوند، مانند عزت او، بی‌بدیل و بی‌همتاست.\nوَاسْتَعْبَدَ الْأَرْبَابَ بِعِزَّتِهِ\nاربابان و مستبدان را به‌واسطهٔ عزت خود به بندگی و عبودیت کشاند.\nخدایی که عزیز است، هیچ بندگی و عبودیت کشاند.\nخدایی که عزیز است، هیچ خویش، همهٔ مدعیان را به بندگی خود درمی‌آورد.\nامیرالمؤمنین در خطبهٔ ۱۸۲ می‌فرماید:\n«لَمْ یُولَدْ سُبْحَانَهُ فَیَکُونَ فِی الْعِزِّ مُشَارِکًا»\nاو نه زاییده شده و نه زاده است تا کسی در عزت با او شریک باشد؛ بنابراین، هیچ شریکی در عزت ندارد.\nدر عالم، لباس عزت شایستهٔ هیچ‌کس نیست، جز خدای متعال؛ و هرکس بخواهد این لباس را بر تن کند، خداوند آن را از تنش بیرون می‌آورد.\nنه فرعون، نه کوچک‌تر از او و نه بزرگ‌تر از او، نمی‌تواند در برابر خداوند بایستد.\nوَسَادَ الْعُظَمَاءَ بِجُودِهِ\nخداوند به‌واسطهٔ بخشش و جود خویش، بر همهٔ بزرگان، سیادت و برتری یافت.\nاو به سبب بخشندگی، آقای همهٔ بزرگان و اشراف شد. یکی از راه‌های رسیدن به سیادت و برتری بر دیگران، جود و بخشش است؛ زیرا هرکس بیشتر ببخشد و برای به راه‌افتادن کار دیگران خود را به‌زحمت بیندازد، به بزرگواری و آقایی می‌رسد. اما شهرت، به‌تنهایی سیادت نمی‌آورد؛ چه‌بسا کسانی که به سبب ذلت و خواری‌شان مشهور شده‌اند، مانند صدام.\nدر کتاب غررالحکم، چندین روایت از امیرالمؤمنین در این زمینه بیان شده است؛ ازجمله:\n«بِالْجُودِ تَکُونُ السِّیَادَةُ؛ سَبَبُ السِّیَادَةِ السَّخَاءُ»\nسیادت در گرو بخشش است. «مَا أَکْمَلَ السِّیَادَةَ مَنْ لَمْ یَصْمَحْ»؛ کسی که گذشت و بخشندگی نداشته باشد، سیادتش کامل نمی‌شود.\nکمال سیادت در بخشندگی است.\nبرخی صفات الهی، مخصوص ذات اقدس خداوند است؛ مانند واجب‌الوجود بودن، علم و مانند آن. اما فرموده است:\n«تَخَلَّقُوا بِأَخْلَاقِ اللَّهِ»\nیعنی انسان می‌تواند در برخی صفات، به اندازهٔ توان و ظرفیت خود، مانند خداوند رفتار کند. ازجمله می‌تواند در حد خود اهل بخشش باشد. در اینجا کمیت بخشش مهم نیست، بلکه برخورداری از صفت بخشندگی اهمیت دارد.\nوَهُوَ الَّذِی أَسْکَنَ الدُّنْیَا خَلْقَهُ\nخداوند، مخلوقات خود را در دنیا سکونت داد.\nحمد و ستایش، مخصوص خدایی است که زمین را برای سکونت انسان و غیرانسان مناسب قرارداد و آن را گهواره‌ای برای آرامش گرداند.\nوَبَعَثَ إِلَی الْجِنِّ وَالْإِنْسِ رُسُلَهُ\nو پیامبران خود را برای جن و انس مبعوث کرد.\nباید خداوند را شکر کنیم که پیامبران را برای هدایت ما فرستاد؛ پیامبرانی که نیرویی پیوسته برای توجه دادن و تذکردادن به انسان‌ها هستند.\nدر ذیل آیهٔ ان ۱۳۰ سورهٔ انعام آمده است:\n«یَا مَعْشَرَ الْجِنِّ وَالْإِنْسِ أَلَمْ یَأْتِکُمْ رُسُلٌ مِنْکُمْ یَقُصُّونَ عَلَیْکُمْ آیَاتِی وَیُنْذِرُونَکُمْ وَ…»\nاگر «رسول» در اینجا به معنای اصطلاحی، یعنی پیامبر، باشد، معنایش این است که در میان طایفهٔ جن نیز پیامبری از جنس خودشان قرار داده‌ایم؛ اما بسیاری از علما باتوجه‌به قرائن و روایات، «رسول» را به معنای لغوی آن، یعنی «فرستاده‌شده»، گرفته‌اند.\nبنابراین، انبیا از جنس انسان بوده‌اند؛ زیرا انسان اشرف و افضل است. آنان برای هدایت جن‌ها، نمایندگانی از جنس خود جنیان انتخاب می‌کردند و سخنان خود را به آنان می‌رساندند. آن نمایندگان نیز در میان جن‌ها می‌رفتند و با آنان گفت‌وگو می‌کردند.\nپس مشهور این است که جن‌ها باید از پیامبرانِ انسان تبعیت کنند.\nدر ادامه، حضرت چند هدف پیامبران را بیان می‌فرماید:\nلِیَکْشِفُوا لَهُمْ عَنْ غِطَائِهَا\n۱. پیامبران آمدند تا پرده از چهرهٔ دنیا بردارند.\nدنیا خود را برای انسان‌ها بسیار آراسته می‌کند تا آنان را مجذوب سازد. جاذبه‌های دنیا بسیار زیاد است و می‌تواند همه را گرفتار کند؛ اما پیامبران آمدند تا حقیقت دنیا را نشان دهند و بگویند دنیا محل دلبری و دل‌بستن نیست، بلکه جای فنا، رنج و نابودی است.\nوَلِیُحَذِّرُوهُمْ مِنْ ضَرَّائِهَا\n۲. پیامبران آمدند تا انسان‌ها را از گرفتاری‌ها و سختی‌های دنیا بیم دهند و هشدار دهند.\nدست انسان باید به ریسمان الهی متصل باشد تا در دنیا غرق و سرگردان نشود.\nوَلِیَضْرِبُوا لَهُمْ أَمْثَالَهَا\n۳. پیامبران آمدند تا برای مردم، نمونهینیم، همان را تمامِ دنیا تصور می در طول عمر خود، هرچه را می‌بینیم، همان را تمامِ دنیا تصور می‌کنیم؛ اما پیامبران آمدند تا برای ما مثال بزنند و داستان‌ها و عبرت‌های گذشتگان را نقل کنند تا آگاه و هوشیار شویم. این، چه نعمت بزرگی است که باید به‌خاطر آن خدا را شکرگزار باشیم.\nوَلِیُبَصِّرُوهُمْ عُیُوبَهَا\n۴. پیامبران آمدند تاچشم انسان‌ها را باز کنند و به آنان بصیرت ببخشند تا عیوب دنیا را ببینند.\nعاشق دنیا، مانند عاشق لیلی، هرگز عیوب معشوق خود را نمی‌بیند. پیامبران آمدند تا به انسان‌ها بگویند دنیا جای عاشقی و دل‌باختگی نیست.\nحضرت ابراهیم خلیل فرمود:\n«إِنِّی لَا أُحِبُّ الْآفِلِینَ»\nمن هر چیزی را که فانی شدنی است، دوست ندارم. بزرگ‌ترین عیب دنیا همین فنا و زوال‌پذیری آن است.\nحضرت امیرالمؤمنین در توصیف برادران خود فرمود: خوشا به حال کسانی که دنیای زودگذر را فروختند و آخرتِ گسترده و همیشگی را خریدند؛ آنان برادران من هستند.\nوَلِیَهْجُمُوا عَلَیْهِمْ بِمُعْتَبَرٍ مِنْ تَصَرُّفِ مَصَاحِّهَا وَأَسْقَامِهَا\n۵. هدف از آمدن پیامبران این بود که با کلمات قاطع خود بر جن و انس هجوم‌آورند و با تازیانهٔ کلام، انسان را از طریق عبرت‌هایی برگرفته از دگرگونی‌های دنیا، تندرستی‌ها و بیماری‌ها، تربیت کنند.\nگاهی برای تأثیرگذاری بر دیگران، باید حرکتی قاطع و هجومی انجام داد. پیامبران با بیان عبرت‌هایی از تاریخ، مردم را به تفکر وامی‌داشتند و از آنان می‌پرسیدند: آیا می‌خواهید سرانجامتان مانند عاد و ثمود و دیگر اقوام نابودشده باشد؟\nیکی از عبرت‌هایی که حضرت بیان می‌کند، این است که تندرستی و بیماری جابه‌جا می‌شوند. پیامبران آمدند تا هشدار دهند که اگر امروز خوش و برخوردار هستید، مست نعمت نشوید؛ زیرا فردا روز بیماری نیز فرا خواهد رسید و اگر بیمار یا فقیر هستید، ناامید نباشید؛ زیرا فردا روز خوشی نیز خواهد آمد.\nانسان، اگر حقیقت دنیا را بشناسد، دگرگونی و تغییرپذیری آن را نیز خواهد شناخت.\nوَحَلَالِهَا وَحَرَامِهَا\n۶. پیامبران آمدند تا حلال‌ها و حرام‌های دنیا را به جن و انس نشان دهند.\nفطرت و روح انسان خداجوست؛ اما انسان نمی‌داند خدا را با چه لفظی بخواند و چگونه با او دعا کند. اگر صحیفهٔ سجادیه نبود، ما شیوهٔ سخن‌گفتن باخدا را نمی‌دانستیم؛ و اگر نهج‌البلاغه نبود، از توحید، شیوهٔ حکومت‌داری، اخلاق و دیگر معارف آگاهی نداشتیم. همهٔ این‌ها از برکت نبوت و امامت است.\nهمهٔ حلال‌ها و حرام‌ها از طریق پیامبران و اولیای الهی به ما رسیده است و این، جای شکر دارد. حلال و حرام، امور اعتباریِ بی‌پایه نیستند؛ بلکه حقایقی‌اند که خداوند بر اساس آن‌ها حکم صادر کرده است. احکام تابع به آن‌ها عملد هستند و اگر خداوند آن‌ها را برای ما بیان نمی‌کرد، به آن‌ها عمل نمی‌کردیم و در نتیجه، زیان می‌دیدیم.\nوَمَا أَعَدَّ اللَّهُ لِلْمُطِیعِینَ مِنْهُمْ وَالْعُصَاةِ مِنْ جَنَّةٍ وَنَارٍ\n۷. پیامبران آمدند تا آنچه را خداوند برای فرمان‌بردارانِ جن و انس و گناهکارانِ آنان، از بهشت و جهنم، آماده کرده است، به ما معرفی کنند.\nاگر پیامبران نبودند، نمی‌دانستیم کدام عمل ما را بهشتی و کدام عمل، ما را جهنمی می‌کند.\nپیامبران آمدند تا این هفت فلسفه و هدف را به ما یادآوری کنند و این کار را نیز انجام دادند. اکنون:\n«فَإِمَّا شَاکِرًا وَإِمَّا کَفُورًا»\nأَحْمَدُهُ إِلَی نَفْسِهِ کَمَا اسْتَحْمَدَ إِلَی خَلْقِهِ\nخداوند را همان‌گونه ستایش می‌کنم که خود از مخلوقاتش طلب حمد و ستایش کرده است.\nخداوند متعال نعمت را عطا کرده و سپس فرموده است که از بندگان خود انتظار حمد و سپاس دارد.\nتشکر دیگران از انسان، گاهی موجب غرور، خودپسندی و منت‌گذاشتن می‌شود؛ اما شکر بنده برای خداوند سودی ندارد. خداوند می‌فروَجَعَلَ باشید تا نعمت خود را بر شما بیفزایم.\nوَجَعَلَ لِکُلِّ شَیْءٍ قَدْرًا\nخداوند برای هر چیزی اندازه و مقدار مشخصی قرارداد.\nوَلِکُلِّ قَدْرٍ أَجَلًا\nو برای هر مقدار مشخصی، پایانی قرارداد.\nدر بحث قضاوقدر، هنگامی که خداوند دربارهٔ انجام کاری تصمیم می‌گیرد، مانند مرگ و آفرینش، آن را قضا می‌گویند؛ اما چگونگی و جزئیات این امر، مقدرات نامیده می‌شود.\nخداوند هر چیز خاص را با اندازه و مقدار خاصی آفریده است و همین اندازه، آن را محدود می‌کند. هر چیز نیز مدت، اجل و سرآمدی دارد.\nوَلِکُلِّ أَجَلٍ کِتَابًا\nتمام این پایان‌ها و سرآمدها در لوح محفوظ خداوند مکتوب است و هیچ‌کس نمی‌تواند از کتابی که خداوند نوشته است، تخطی کند.\nخداوند قدرتی بی‌انتها دارد و مجموعهٔ قضاها، قدرها و اجل‌ها در علم او ثابت است. هیچ‌چیزی خارج از علم خداوند نیست؛ بنابراین، در عالم نه تصادف حاکم است و نه شانس، بلکه مقدرات الهی بر عالم حکومت می‌کنند.\nامام سجاد علیه‌السلام در دعای سیزدهم صحیفهٔ سجادیه می‌فرماید: ای خدایی که به کسی نیاز نداری، اما همه به تو نیازمندند؛ همه به سبب تو بی‌نیاز می‌شوند. تو خدایی هستی که هرچه مردم از تو درخواست کنند، به آنان می‌بخشی و چیزی از خزانه‌های تو کم نمی‌شود.\nداستان درخواست مردم از خداوند، مانند فروبردن نخی در اقیانوس است؛ یک نخ چه اندازه از آب اقیانوس کم می‌کند؟\nتو خدایی هستی که وسیله‌ها نمی‌توانند حکمتت را تغییر دهند. دعاکردن، شرکت در روضه و حضور در جلسه، ازجمله این وسیله‌ها هستند؛ اما حکمت خداوند بر همهٔ آن‌ها غالب است. خداوند مانند انسان تحت‌تأثیر قرار نمی‌گیرد تا صرفاً به سبب تأثیر یک وسیله، حاجتی را برآورده کند؛ بلکه اگر وسیله‌ای را که به درگاه او می‌بریم، حکیمانه باشد، به آن عنایت می‌کند وگرنه برآورده نمی‌شود. دعای عاقلانه نیز بر اساس قواعد الهی مستجاب می‌شود.\nارتباط قرآن با انبیا\nهر پیامبری کتابی داشته است و قرآن، کتاب پیامبر خاتم است و اهداف رسالت پیامبران را دنبال می‌کند.\nویژگی‌های قرآن\nفَالْقُرْآنُ آمِرٌ زَاجِرٌ\n۱. قرآن امرکننده و بازدارنده است.\nدر قرآن، «أَقِمِ الصَّلَاةَ» وجود دارد و «لَا تَتَّبِعُوا الشَّیْطَانَ» نیز آمده است.\nوَصَامِتٌ نَاطِقٌ\n۲. قرآن صامت و ناطق است.\nصامت و ساکت بودن، ظاهر قرآن است؛ و ناطق‌بودن و سخن‌گفتن آن، به‌وسیلهٔ اهل‌بیت صورت می‌گیرد.\nاین عبارت دو معنا دارد:\nالف) از جهت ظاهر، قرآن ساکت است و سخن نمی‌گوید.\nب) قرآن ازاین‌جهت ناطق است که دارای سخن و محتواست و پیام و مطلبی گویا در خود دارد.\nقرآن در برخی موارد سکوت می‌کند، اما سکوتش حکیمانه است؛ و در برخی مواقع سخن می‌گوید که آن سخن نیز حکیمانه است.\nبرای نمونه، دربارهٔ روح می‌فرماید:\n«قُلِ الرُّوحُ مِنْ أَمْرِ رَبِّی»\nیا دربارهٔ زمان قیامت می‌فرَکَ عَنِ السَّاعَةِکَ عَنِ السَّاعَةِ أَیَّانَ مُرْسَاهَا قُلْ عِلْمُهَا عِنْدَ رَبِّی»\nهمچنین دربارهٔ انفاق، هنگامی که از پیامبر می‌پرسیدند، می‌فرماید:\n«یَسْأَلُونَکَ مَاذَا یُنْفِقُونَ قُلْ مَا أَنْفَقْتُمْ مِنْ خَیْرٍ»\nافراد ثروتمند می‌پرسیدند چگونه انفاق کنیم. اگر قرآن پاسخ می‌داد که فقط مقدار مشخصی انفاق کنید، افراد ناداری مانند ابوذر ره و اصحاب صفّه دل‌شکسته می‌شدند؛ زیرا پولی برای انفاق نداشتند. ازاین‌رو، قرآن می‌فرماید هرچه را می‌خواهید انفاق کنید؛ خداوند آن را می‌بیند. آنان مصداق می‌خواستند، اما خداوند پاسخ جزئی و مشخصی نداد. گاهی سکوت‌کردن، همان پاسخ‌دادن است.\nحضرت در خطبهٔ ۱۵۴ دربارهٔ اهل‌بیت می‌فرماید: اگر سخن بگویند، سخنشان راست است و سکوتشان نیز به نفع طرف مقابل است.\nحُجَّةُ اللَّهِ عَلَی خَلْقِهِ\n۳. قرآن حجت خدا بر مخلوقات است؛ همان‌گونه که امام حجت است. با قرآن بر ما احتجاج می‌کنند: چرا قرآن را خواندی، اما به آن عمل نکردی؟\nأَخَذَ عَلَیْهِ مِیثَاقَهُمْ\n۴. خداوند در زمانی با انسان عهد بست و مفاد این عهد آن بود که انسان قرآن را بگیرد و به آن عمل کند.\nوَارْتَهَنَ عَلَیْهِ أَنْفُسَهُمْ\n۵. خداوند همگان را در برابر عمل به قرآن به گرو گرفت.\nهمهٔ شما در رهن قرآن هستید و بهای آزادی شما از این گرو، خود شما هستید. با عمل به قرآن، از این رهن و گرو آزاد می‌شوید.\nوَارْتَهَنَ عَلَیْهِ أَنْفُسَهُمْ\nخداوند آنان را در گرو دستورات خود قرار داده است.\nهمه در گرو عمل به قرآن هستند. در فقه، بحث رهن اهمیت بسیاری دارد؛ اینکه چیزی را نزد چه کسی گرو بگذاریم و در برابر آن، وسیله یا مالی را دریافت کنیم. ما همه در رهن قرآن هستیم تا به آن عمل کنیم و آزاد شویم؛ اما اگر کسی به قرآن عمل نکند، در زندان دنیا گرفتار می‌شود.\nبااین‌حال، اکنون ماجرا برعکس شده است و برخی می‌گویند اگر بندهٔ قرآن شویم، گرفتار خواهیم شد.\nآزادی و حریت، در عمل به قرآن است.\nوَأَتَمَّ نُورَهُ\n۶. خداوند به سبب قرآن، نور خود را کامل کرد. قرآن، کامل‌کنندهٔ نور خداوند است.\nوَأَکْمَلَ بِهِ دِینَهُ\n۷. خداوند به سبب قرآن، دین خود را کامل کرد.\nبدون قرآن، دین ناقص بود؛ همان‌گونه که بدون ولایت امیرالمؤمنین علیه‌السلام، دین ناقص می‌ماند.\nوَقَبَضَ نَبِیَّهُ صَلَّی اللَّهُ عَلَیْهِ وَآلِهِ وَقَدْ فَرَغَ إِلَی الْخَلْقِ مِنْ أَحْکَامِ الْهُدَی بِهِ\nخداوند هنگامی پیامبر را قبض روح کرد که پیامبر، احکامی را که باید به مردم می‌رساند، به طور کامل به آنان ابلاغ کرده بود.\nرسول اکرم صلی‌الله علیه و آله تمام احکام دین و هدایت را به مردم رساند و سپس از دنیا رفت. قرآن هم کامل است و هم حجت؛ بنابراین، عذری باقی نمی‌گذارد. پیامبر نیز احکام قرآن را به طور کامل بیان کرد. اکنون این ما هستیم که در گرو دین و قرآن قرار داریم: یا عمل می‌کنیم و آزاد می‌شویم، یا عمل نمی‌کنیم و همیشه در بند خواهیم ماند.\nفَعَظِّمُوا مِنْهُ مَا عَظَّمَ مِنْ نَفْسِهِ\nخداوند متعال را همان‌گونه تعظیم کنید که خود، خویشتن را در قرآن تعظیم کرده است.\nانتخاب نام و صفت برای خداوند باید به‌گونه‌ای باشد که بر ضعف و نقص دلالت نکند؛ زیرا در ذات او هیچ نقصی راه ندارد.\nخداوند به دلیل امور زیر شایستهٔ احترام و تکریم است:\nاو چیزی از دین خود را پنهان نکرد و هرآنچه را لازم بود، برای شما آشکار ساخت.\nوَلَمْ یَتْرُکْ شَیْئًا رَضِیَهُ أَوْ کَرِهَهُ إِلَّا وَجَعَلَ لَهُ عَلَمًا بَادِیًا\nخداوند هرآنچه را دوست دارد و هرآنچه را نمی‌پسندد، آشکارا بیان کرده است.\nاو برای محبوب‌ها و مبغوض‌های خود نشانه‌ای روشن قرار داده است.\nوَآیَةً مُحْکَمَةً تَدْعُوا إِلَیْهِ\nخداوند از این مجموعه، نشانه‌ای آشکار و آیه‌ای محکم، مانند حدیث قدسی، حدیث نبوی، قرآن و عقل، قرار داده است تا از کارهای ناپسند دوری کنیم و کارهای محبوب خداوند را انجام دهیم.\nفَرِضَاهُ فِیمَا بَقِیَ وَاحِدٌ وَسَخَطُهُ فِیمَا بَقِیَ وَاحِدٌ\nاین آیهٔ محکم، شما را از کارهایی که مورد کراهت خداوند است، بازمی‌دارد و به‌سوی کارهایی که محبوب خداست، فرامی‌خواند.\nفَإِنَّهُ لَمْ یُخْفِ عَنْکُمْ شَیْئًا مِنْ دِینِهِ\nخداوند هیچ‌چیزی از دین خود را از شما پنهان نکرده است.\nخداوند هرآنچه را به صلاح یا زیان ماست، در قرآن بیان فرموده است؛ وگرنه جایی برای محاسبه باقی نمی‌ماند.\nوَلَمْ یَتْرُکْ شَیْئًا رَضِیَهُ أَوْ کَرِهَهُ إِلَّا وَجَعَلَ لَهُ عَلَمًا بَادِیًا\nخداوند در بیان هرآنچه مورد رضایت یا کراهت او بوده، کوتاهی نکرده و با نشانه‌های آشکار، آن را به ما گفته است.\nاو برای محبوب‌ها و مبغوض‌های خود نشانه‌ای آشکار قرار داده است.\nوَآیَةً مُحْکَمَةً تَدْعُوا إِلَیْهِ\nخداوند نشانه‌ای آشکار و آیه‌ای محکم، مانند حدیث قدسی، حدیث نبوی، قرآن و عقل، قرار داده است تا از کارهای ناپسند دوری کنیم و فعل محبوب را انجام دهیم.\nفَرِضَاهُ فِیمَا بَقِیَ وَاحِدٌ وَسَخَطُهُ فِیمَا بَقِیَ وَاحِدٌ\nاین آیهٔ محکم، شما را از کارهای مورد کراهت بازمی‌دارد و به‌سوی کارهایی که محبوب خداوند است، دعوت می‌کند.\nاکنون همه می‌دانند حکم، فرمان، رضایت و کراهت خداوند در چیست؛ بنابراین، عمل‌کردن یا عمل‌نکردن، به خود آنان بستگی دارد.\nوَآیَةً مُحْکَمَةً تَدْعُوا إِلَیْهِ\nصلاح و زیان ما با یک آیه و نشانهٔ محکم بیان شده است؛ یا این آیه و نشانهٔ محکم، ما را به‌سوی آن دعوت کرده است.\nاحکام خداوند، دیروز و امروز ندارد؛ اما احکام انسان ممکن است دیروز و امروز داشته باشد، زیرا انسان باید تجربه کسب کند و بر اساس تجربه‌های خود تصمیم بگیرد.\nفَرِضَاهُ فِیمَا بَقِیَ وَاحِدٌ وَسَخَطُهُ فِیمَا بَقِیَ وَاحِدٌ\nپس خشنودی و خشم خداوند درگذشته و حال یکسان است.\nخشنودی و غضب خداوند، دیروز و امروز ندارد. سخن خداوند از روز نخست تا ابد یکی است. اگرچه ادیان به‌تدریج کامل شده‌اند، سخن خداوند تغییر نمی‌کند؛ چنان‌که پیامبر فرمود:\n«حَلَالُ مُحَمَّدٍ صَلَّی اللَّهُ عَلَیْهِ وَآلِهِ حَلَالٌ أَبَدًا إِلَی یَوْمِ الْقِیَامَةِ، وَحَرَامُهُ حَرَامٌ إِلَی یَوْمِ الْقِیَامَةِ»\nدر خطبهٔ ۱۷۶، حضرت می‌فرماید هرچه را خداوند امروز حلال کرده است، تا همیشه حلال خواهد بود.\nمردم نمی‌توانند برای دین خداوند حکم جدیدی تعیین کنند. هرچه را خداوند دیروز حلال کرده، امروز نیز حلال است؛ و هرچه را حرام کرده، امروز نیز حرام است. مردم نمی‌توانند برای خداوند تعیین تکلیف کنند؛ حکم، همان است که خداوند صادر کرده است.\nغَفَرَ اللَّهُ لِی وَلَکُمْ، وَالْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِینَ","بخش دوم\nمتن:\nوَ اعْلَمُوا أَنَّهُ لَنْ يَرْضَى عَنْكُمْ بِشَيْءٍ سَخِطَهُ عَلَى مَنْ كَانَ قَبْلَكُمْ وَ لَنْ يَسْخَطَ عَلَيْكُمْ بِشَيْءٍ رَضِيَهُ مِمَّنْ كَانَ قَبْلَكُمْ؛ وَ إِنَّمَا تَسِيرُونَ فِي أَثَرٍ بَيِّنٍ وَ تَتَكَلَّمُونَ بِرَجْعِ قَوْلٍ قَدْ قَالَهُ الرِّجَالُ مِنْ قَبْلِكُمْ؛ قَدْ كَفَاكُمْ مَئُونَةَ دُنْيَاكُمْ وَ حَثَّكُمْ عَلَى الشُّكْرِ وَ افْتَرَضَ مِنْ أَلْسِنَتِكُمُ الذِّكْرَ.\nالوصية بالتقوى:\nوَ أَوْصَاكُمْ بِالتَّقْوَى وَ جَعَلَهَا مُنْتَهَى رِضَاهُ وَ حَاجَتَهُ مِنْ خَلْقِهِ، فَاتَّقُوا اللَّهَ الَّذِي أَنْتُمْ بِعَيْنِهِ وَ نَوَاصِيكُمْ بِيَدِهِ وَ تَقَلُّبُكُمْ فِي قَبْضَتِهِ. إِنْ أَسْرَرْتُمْ عَلِمَهُ وَ إِنْ أَعْلَنْتُمْ كَتَبَهُ؛ قَدْ وَكَّلَ بِذَلِكَ حَفَظَةً كِرَاماً لَا يُسْقِطُونَ حَقّاً وَ لَا يُثْبِتُونَ بَاطِلًا. وَ اعْلَمُوا أَنَّهُ \"مَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجاً\" مِنَ الْفِتَنِ وَ نُوراً مِنَ الظُّلَمِ، وَ يُخَلِّدْهُ فِيمَا اشْتَهَتْ نَفْسُهُ وَ يُنْزِلْهُ مَنْزِلَ الْكَرَامَةِ عِنْدَهُ فِي دَارٍ اصْطَنَعَهَا لِنَفْسِهِ، ظِلُّهَا عَرْشُهُ وَ نُورُهَا بَهْجَتُهُ وَ زُوَّارُهَا مَلَائِكَتُهُ وَ رُفَقَاؤُهَا رُسُلُهُ. فَبَادِرُوا الْمَعَادَ وَ سَابِقُوا الْآجَالَ، فَإِنَّ النَّاسَ يُوشِكُ أَنْ يَنْقَطِعَ بِهِمُ الْأَمَلُ وَ يَرْهَقَهُمُ الْأَجَلُ وَ يُسَدَّ عَنْهُمْ بَابُ التَّوْبَةِ؛ فَقَدْ أَصْبَحْتُمْ فِي مِثْلِ مَا سَأَلَ إِلَيْهِ الرَّجْعَةَ مَنْ كَانَ قَبْلَكُمْ وَ أَنْتُمْ بَنُو سَبِيلٍ عَلَى سَفَرٍ مِنْ دَارٍ لَيْسَتْ بِدَارِكُمْ، وَ قَدْ أُوذِنْتُمْ مِنْهَا بِالارْتِحَالِ وَ أُمِرْتُمْ فِيهَا بِالزَّادِ.\nوَ اعْلَمُوا أَنَّهُ لَيْسَ لِهَذَا الْجِلْدِ الرَّقِيقِ صَبْرٌ عَلَى النَّارِ، فَارْحَمُوا نُفُوسَكُمْ؛ فَإِنَّكُمْ قَدْ جَرَّبْتُمُوهَا فِي مَصَائِبِ الدُّنْيَا، أَفَرَأَيْتُمْ جَزَعَ أَحَدِكُمْ مِنَ الشَّوْكَةِ تُصِيبُهُ وَ الْعَثْرَةِ تُدْمِيهِ وَ الرَّمْضَاءِ تُحْرِقُهُ، فَكَيْفَ إِذَا كَانَ بَيْنَ طَابَقَيْنِ مِنْ نَارٍ، ضَجِيعَ حَجَرٍ وَ قَرِينَ شَيْطَانٍ؟ أَعَلِمْتُمْ أَنَّ مَالِكاً إِذَا غَضِبَ عَلَى النَّارِ حَطَمَ بَعْضُهَا بَعْضاً لِغَضَبِهِ، وَ إِذَا زَجَرَهَا تَوَثَّبَتْ بَيْنَ أَبْوَابِهَا جَزَعاً مِنْ زَجْرَتِهِ؟\nترجمه:\nبدانيد خداوند هيچ گاه به سبب کارى که بر پيشينيان خشم گرفته خشنود نمى شود و هرگز بر شما به سبب چيزى که از پيشينيان راضى شده است، خشمگين نمى گردد. (آرى) شما در راه روشنى گام بر مى داريد (که همه انبيا به آن دعوت کرده اند) و همان سخنى را مى گوييد که بزرگان پيش از شما گفته اند.\nخداوند نياز دنياى شما را برطرف ساخته و شما را به شکر نعمتهايش ترغيب کرده (تا نعمتش را بر شما افزون کند) و ذکر و يادش را با زبان بر شما واجب ساخته است (تا دلهايتان همواره بيدار باشد).\nحرکات شما در اختيار وى قرار دارد. او کسى است که اگر کار خود را پنهان کنيد مى داند و اگر آشکار سازيد ثبت مى کند، پاسداران والامقامى براى ثبت اعمال شما گماشته که از هيچ حقّى غفلت نمى ورزند و چيزى را بيهوده ثبت نمى کنند. بدانيد آن کس که تقوا پيشه کند خداوند راهى براى رهايى از فتنه ها به رويش مى گشايد و نورى در دل تاريکيها به او اعطا مى کند، او را در آنجا که دوست دارد و به آن علاقه مند است (در بهشت) براى هميشه مخلّد مى سازد و در جايگاه والايى نزد خود در سرايى که آن را براى خاصّان خويش ساخته است جاى مى دهد. همان جايى که سايه اش از عرش خداست و نور و روشنايى اش جمال اوست، زائرانش فرشتگان و يارانش پيامبران خدا هستند.\nحال که چنين است به سوى معاد (با اعمال صالح) بر يکديگر سبقت جوييد و بر سرآمد زندگى خود پيشى گيريد، زيرا نزديک است آرزوهاى مردم قطع گردد و مرگ آنها را در آغوش کشد و درهاى توبه به رويشان بسته شود (بدانيد) شما همانند کسانى هستيد که قبل از شما بودند; مرگشان فرا رسيد و تقاضاى بازگشت به اين جهان کردند (اما پذيرفته نشد) و همچون رهروانى در حال کوچ کردن از خانه اى هستيد که خانه شما نيست، فرمان کوچ به شما داده شده و دستور تهيّه زاد و توشه (از اين سرا) را نيز به شما داده اند.\nبدانيد اين پوست نازکِ تنِ (انسان) طاقت آتش دوزخ را ندارد، بنابراين بر خويشتن رحم کنيد، چنان که شما اين حقيقت را درباره خويش در مصائب دنيا آزموده ايد. آيا ناراحتى يکى از شما را که خارى به بدنش فرو مى رود و يا زمين خوردنى که او را کمى مجروح مى سازد و يا ريگهاى داغ بيابان (در فصل گرما) که او را آزار مى دهد، مشاهده کرده ايد؟ حال چگونه خواهيد بود هنگامى که در ميان دو طبقه از آتش برکنار سنگ هاى گداخته در مجاورت شيطان قرار گيريد؟ آيا مى دانيد آن گاه که مالک دوزخ بر آتش خشم مى گيرد، آتشها روى هم مى غلتند و يکديگر را مى کوبند (و شعله هاى عظيم از درون آنها بر مى خيزد) و آن گاه که بر آتش فرياد زند از وحشت فريادش قطعات عظيم آتش در ميان درهاى جهنم به هر سو پرتاب مى شوند!\nتفسیر:\nتوصیه به تقوا\nامیرالمؤمنین صلوات الله و سلام علیه در بخش قبل فرمود:\nآنچه را که خدادوست ندارد و کراهت می‌دارد، فرقی بین دیروز و امروز نیست. حلال و حرام کم‌وزیاد نمی‌شود و در علم الهی ثابت است.\n♦️ وَاعْلَمُوا أَنَّهُ لَنْ یرْضَیٰ عَنْکمْ بِشَیءٍ سَخِطَهُ عَلَیٰ مَنْ کانَ قَبْلَکمْ\nیقین داشته باشید خداوند با کاری از شما خشنود نمی‌شود که به نفرات قبلی شما با همان کار سخط گرفته است.\nاگر اقوام گذشته لوط و ثمود را عذاب کرد، ممکن نیست با همان عمل شما را گرامی بدارد. هر چه دیروز ناپسند بود، امروز هم ناپسند است.\n♦️ وَلَنْ یسْخَطَ عَلَیکمْ بِشَیءٍ رَضِیهُ مِمَّنْ کانَ قَبْلَکمْ\nهرگز این‌طور نیست که امروز چیزی را بر شما ناپسند بدارد، درحالی‌که درگذشته مورد رضایت الهی بوده است. احکام الهی همیشه ثابت است.\nدین هر چه جلوتر آمد تکمیل شد تا رسید به اسلام که کامل‌ترین دین شد. اما اخلاقیات، توحید، معاد در همه ادیان ثابت است.\nکسی را با کفر به بهشت نمی‌برد و امروز هم با کفر نمی‌برد.\nدر خطبه ۱۹۲ فرمود: خدا با کاری که فرشته‌ای را از بهشت خارج کرد، انسانی را با آن به بهشت نمی‌برد. تکبر شیطان سبب خروج از بهشت شد؛ چگونه انسان با تکبر به بهشت وارد شود؟!\n\nقاعدهٔ کلی:\nرضایت خدا در آینده که می‌آید واحد است.\nرضایت او درگذشته به فعلی، همان است که در آینده می‌آید.\nو سخط خدا از گذشته تا آینده واحد است و تغییر نمی‌کند.\nرضایت و خشم خدا، در تمام ادوار ثابت بوده است.\nاگر برای اقوام گذشته انذار داده بود، این انذار برای آینده هم هست. همیشگی است.\nاگر در اقوام گذشته فعلی حسنه را دوست داشت، در آینده همان را دوست می‌دارد. تغییر نمی‌کند.\n\nدر این دو جمله شبهه ایجاد می‌شود:\nپس چرا ادیان آمدند؟\nچرا حکم ادیان مختلف بود؟\nدرحالی‌که حکمی مثل شراب ابتدای اسلام و یا ازدواج دو خواهر با یک شخص در زمان موسی بن عمران حلال بود، در زمان دیگر حرام شد؟\n\nپاسخ ۱: می‌فرماید «مَنْ کانَ قَبْلَکمْ»؛ صحبت از قبل اسلام نیست.\nصحبت از زمان پیامبر است؛ هر چه واجب یا حرام شد از ابتدا تا انتها، واجب و حرام بودن آن استمرار تا ابد هست.\n\nپاسخ ۲: اگر مقصود حضرت اقوام گذشته بود نه‌فقط ابتدای اسلام، این چگونه است؟\nفروع در ادیان متفاوت بوده است؛ ازدواج دو خواهر زمانی حلال و زمانی حرام شد.\nفروع ربطی به اصول ندارد.\nاصول تمام ادیان واحد بوده و رضایت و سخط در اصول همان است. (توحید، اصل پرستش، نفی شرک، معادباوری) این اصول در تمام ادیان ثابت بوده است؛ توحید محبوب خدا بوده و شرک را کراهت داشته و تغییر هم نکرده است.\nکلیت ثابت است. ادیانی که آمدند، هر دین فروع دین قبل را تکمیل کرد، تا رسید به دین پیغمبر خاتم و کامل‌ترین شد.\n\n♦️ وَإِنَّمَا تَسِیرُونَ فِی أَثَرٍ بَینٍ\n\nبندگان خدا، شما مسیر گذشتگان را می‌روید؛ در یک راه آشکار [اثر] حرکت می‌کنید.\nگروهی رفتند و شما آمدید؛ در حال تغییر هستید.\n\n♦️ وَتَتَکلَّمُونَ بِرَحْعِ قَوْلٍ قَدْ قَالَهُ الرِّجَالُ مِنْ قَبْلِکمْ\n\nشما سخنی می‌گویید که تکرار سخن [رجع قول] رجال (انبیا و مؤمنین) گذشته است؛ شما گفتگو و تکرار می‌کنید.\nتکرار گذشتگان، یعنی عمل و رفتار انسان‌های صالح که قبل از شما بودند را به کار می‌برید.\n«این جمله خبر هست؛ ولی به داعیهٔ انشا هست. شما این‌طور عمل می‌کنید، یک خبر است؛ ولی همه حرف انبیا را تکرار نمی‌کنند که باید این‌طور باشید و این‌طور عمل کنید.»\nافراد صالح مطیع پیامبر و کتاب بودند.\nمسیر دین‌داری آنان را طی کنید.\nبه‌مانند کلام سلف صالح خود سخن بگویید.\n\n♦️ قَدْ کفَاکمْ مَوُونَةَ دُنْیاکمْ\n\nخداوند مؤونهٔ دنیای شما را تضمین کرده است.\nمؤونه منظور خوردوخوراک نیست، بلکه ابزار و وسائل زندگی است. نیاز به تنفس، هوا و اکسیژن قرار داده؛ نیاز حیاتی، آب قرار داده؛ جلوگیری از تأثیر ضررها، در مقابل اشعهٔ خورشید لایهٔ ازن قرار داده؛\nآنچه برای زندگی دنیا نیاز بود، احتیاجات اولیه همه را تأمین کرده است.\nاگر مؤونه رزق مقدر باشد، برای همه رزقی قرار داده شده و روزی را می‌رساند.\nبه شرطی که ظالمی بر سر راه نباشد و سهم مقدر دیگری را دستبرد نزند که باید او پاسخگو باشد.\n\n♦️ وَحَثَّکمْ عَلَی الشُّکرِ وَافْتَرَضَ مِنْ أَلْسِنَتِکمُ الذِّکرَ\n\nخدا مؤونه داد و تشویق کرد [حَثَّ] به شکرگزاری. اصل نعمت را داد و راه ازدیاد شکر را هم بیان کرد. «وَلَئِنْ شَکرْتُمْ لَأَزِیدَنَّکمْ - ابراهیم - ۷»\n♦️ وَافْتَرَضَ مِنْ أَلْسِنَتِکمُ الذِّکرَ\nبر شما ذکر شکر را واجب کرد. علاوه بر دادن مؤونه و درخواست شکر به آن اکتفا نکرد؛ علاوه‌برآن واجب هم کرد. در عین واجب عملی، لسان هم پیوسته ذاکر به شکر باشد.\nقرائت قرآن یک حرف است، تدبر در قرآن حرف دیگری؛ بعد از فهم تدبر امر شده قرآن را بلند بخوانید تا به گوش دیگران هم برسد.\n\n♦️ وَأَوْصَاکمْ بِالتَّقْوَیٰ\n\nخدا همه را توصیه کرد به تقوا.\n«وَلَقَدْ وَصَّینَا الَّذِینَ أُوتُوا الْکتَابَ مِنْ قَبْلِکمْ وَإِیاکمْ أَنِ اتَّقُوا اللَّهَ - نساء - ۱۳۱»\nتوصیه کردیم اهل کتاب را که قبل از شما بودند و همین‌طور شما را که تقوای خدا را پیشه خود کنید.\n\n♦️ وَجَعَلَهَا مُنْتَهَیٰ رِضَاهُ\n\nتقوا را مُنتهای رضایت خود قرار داده است.\nهرچه متقی‌تر، کسب رضایت بیشتر است. بیشترین رضایت الهی در گرو تقواست.\n\n♦️ حَاجَتَهُ مِنْ خَلْقِهِ\n\nبالاترین آن، حاجت خدا از خلق است.\nتقوا حاجت خداست از شما.\nخدا هیچ احتیاجی ندارد؛ اما به انسان رو انداخته، خواهش کرده؛\nتقوا آن‌قدر مسئله‌ای مهمی هست که خداوند از شما درخواست کرده که تقوا داشته باشید.\nتنها احتیاج و نیازی که خدا به مردم رو انداخته برای تقواست. آن‌قدر کریم است، به بنده رو می‌زند که باتقوا کار بنده راحت‌تر باشد.\n\n♦️ فَاتَّقُوا اللَّهَ الَّذِی أَنْتُمْ بِأَعْینِهِ\n\nتقوای خدایی داشته باشید که زیر نگاه و دید او هستید. «وَلِتُصْنَعَ عَلَیٰ عَینِی - قصص - ۱۰»\nزیر نظر و نگاه من بزرگ و ساخته می‌شوی.\n«أَلَمْ تَرَ أَنَّ اللَّهَ یرَیٰ» عالم محضر خداست؛ در محضر او گناه نکنید.\n\n♦️ وَنَوَاصِیکمْ بِیدِهِ وَتَقَلُّبُکمْ فِی قَبْضَتِهِ\n\nموی سرِ پیشانی [نواصی]؛ تمام اختیار شما به دست خداست.\n(موی سرِ پیشانی حیوان وقتی کشیده می‌شود زود رام و تسلیم می‌شود و از خود اختیاری ندارد.)\nتقوای خدایی که تمام حالات و حرکات اعضای شما در قبضهٔ قدرت اوست.\n\n♦️ إِنْ أَسَرْرْتُمْ عَلِمَهُ\n\nهر چه را پنهان کنید، همه چیز به ظواهر نیست؛ اسرار را خدا می‌داند.\n\n♦️ وَإِنْ أَعْلَنْتُمْ کتَبَهُ\n\n(از کلمات رحمتی و اوج رحمت خدا را بیان می‌کند.) باوجوداینکه همه چیز را می‌داند؛ اما ثبت نمی‌کند؛ فقط آنچه که آشکار و به عمل می‌رسد [أعلنتم] ملائک می‌نویسند.\nصرف فکر باشد، با اینکه می‌داند؛ ولی ثبت نمی‌کند.\nعلم خدا به همه چیز هست؛ اما ملائک به همه چیز علم ندارند. خدا یک حجاب‌هایی قرار داده. ملک ثبت اعمال روزانه عوض می‌شود و هرگز برنمی‌گردد تا روز شهادت حاضر شود. ثابت نبودن آنها برای حفظ آبروی اشرف مخلوقات، انسان است.\n«وَالشَّاهِدَ لِمَا خَفِی عَنْهُمْ - دعای کمیل»\nتو شاهد بر اموری هستی که حتی از ملائک هم مخفی هستند.\nرسول مکرم صلی‌الله علیه و آله فرمود:\n«مَنْ عُفِی بِأُمَّتِی … مَا لَمْ یتَکلَّمُوا وَمَا لَمْ یفْعَلُوا» گناهانی که به ذهن خطور می‌کند؛ ولی به عمل نمی‌رسد، عفو شده به شرطی که با اجرا درنیاید.\nفکر گناه اثر منفی دارد؛ اگر پیوسته فکر گناه باشد در عملکرد اثر خود را می‌گذارد و به‌راحتی صورت می‌گیرد. ابتدا قبح گناه در ذهن می‌شکند، با تکرار، در عمل هم راحت شکسته می‌شود.\n\n♦️ قَدْ وَکلَ بِکمْ حَفَظَةً کرَامًا\n\nخداوند برای حفظ اعمال، ملائک بزرگی را موکل کرده است.\n♦️ لَا یسْقِطُونَ حَقًّا وَلَا یثْبِتُونَ بَاطِلًا\nهیچ حقی از قلم آنها ساقط نمی‌شود و هیچ باطل و اشتباهی را ثبت نمی‌کنند.\nنه خوبی جا می‌ماند و نه گناه اضافه؛ به‌پای کسی می‌نویسند.\n\n♦️ وَاعْلَمُوا أَنَّهُ مَنْ یتَّقِ اللَّهَ یجْعَلْ لَهُ مَخْرَجًا مِنَ الْفِتَنِ\n\nبدانید که اهل تقوا از فتنه‌ها خارج می‌شود.\n(این جمله تفسیر امیرالمؤمنین از آیه قرآن است - طلاق - ۴)\nرعایت تقوا چندین اثر و نتیجه دارد:\nراه خروج را شرح می‌دهد.\n♦️ یجْعَلْ لَهُ مَخْرَجًا مِنَ الْفِتَنِ\n۱- تقوا راه برون‌رفت از فتنه، راه خروج از گرفتاری را نشان می‌دهد. فضای غبارآلود باعث نمی‌شود که حق را تشخیص ندهد.\n♦️ وَنُورًا مِنَ الظُّلمِ\n۲- در تاریکی و بیراهه، وجود متقی نور می‌شود؛ بمانند فانوس درونی، مسیر را روشن می‌کند.\n♦️ وَیخَلِّدُهُ فِیمَا اشْتَهَتْ نَفْسُهُ\n۳- تقوا می‌تواند خالد کند اهل تقوا را در اموری که اشتها دارد [فِیمَا اشْتَهَتْ]؛\nجاودانه می‌کند در خانه‌ای که شدیداً به آن میل دارد.\nمؤمن این‌طور نیست که هر چه پیش آید خوش آید. به گناه و بی‌عفتی علاقه ندارد، به ایمان علاقه دارد. خدا طوری برنامه عالم را می‌چیند که موارد اشتهایی سر راه متقی قرار بگیرد.\nدر حال خوش، محبت و مودت در ولایت، اشتهای مؤمن این است که حال خوش را از دست ندهد. «فَلَا تَسْلُبْ مِنِّی مَا أَنَا فِیهِ»\nمودت ولایت از او گرفته نشود.\nمؤمن خالد می‌شود در آنچه که میل دارد و خدا همکاری می‌کند که سروکار مؤمن با آنها باشد.\n♦️ وَینْزِلُهُ مَنْزِلَةَ الْکرَامَةِ عِنْدَهُ\n۴- تقوا شخص متقی را در منزل کرامت، نزد خود جای می‌دهد. همسایه و هم‌جوار خدا می‌شود [یا جارِی اللَّصِیق]. وقتی در دنیا هم‌جوار باخدا و قلب باخدا باشد، قیامت هم باخدا همسایه خواهد بود.\n\nاوصاف این منزل کرامت:\n♦️ فِی دَارٍ اصْطَنَعَهَا لِنَفْسِهِ\n- کریم، منزل کرامتی را که برای خودساخته [اصْطَنَعَهَا] عطا می‌کند.\nاز باب اینکه بیت‌الله، شهر الله آمده و خدا نیاز به مکان و ماه و خانه ندارد، از باب شرافت و تعظیم به خدا اسناد داده می‌شود.\n♦️ ظِلُّهَا عَرْشُهُ\n- سایبان این خانه عرش الهی است.\n♦️ وَنُورُهَا بَهْجَتُهُ\n- روشنایی این خانه، خشنودی، رضایت و لبخند خداست. نورانیت بهشت به رضایت خداست.\n♦️ وَزُوَّارُهَا مَلَائِکتُهُ\n- این خانه نه‌تنها نزدیک خدا، بلکه حرم است و برای آن زائر می‌آید و ملائک زائرانی هستند که به‌دور خانه طواف می‌کنند.\n♦️ وَرُفَقَاؤُهَا رُسُلُهُ\n- رفیقان خانه انبیا هستند.\nاین خانه، خانه‌ای است که خدا برای خاستگاه خودساخته؛ آن‌قدر که منسوب شده به او؛ خانه، خانهٔ من است.\nاین جایگاه عظیم برای صاحب تقواست.\n\nتوصیه‌های اخلاقی:\n\n♦️ فَبَادِرُوا الْمَعَادَ\nابتدا شما مبادرت به معاد داشته باشید؛ معادباوری به‌تنهایی کافی نیست.\nعلاوه بر پذیرش معاد، باید اعمال شما در راستای معادباوری باشد.\n۱- معاد را باور داشته باشید.\n۲- سبقت بگیرید در انجام اعمال صالح، متناسب با معاد.\nطوری زندگی کنید که حقیقت مرگ روشن باشد. در مرگ یک انقطاع حاصل می‌شود. پس قبل از اینکه مرگ برسد، آن انقطاع را به دست آورید. دلبسته و وابسته بودن به دنیا تمام شود.\n\n♦️ وَسَابِقُوا إِلَی الْآجَالِ\nقبل از اینکه مرگ شما را بگیرد، شما بر مرگ پیشی بگیرید. (منظور خودکشی نیست)\nقبل از حاصل‌شدن، خود منقطع بشوید. آماده مرگ باشید.\n\n♦️ فَإِنَّ النَّاسَ یوشِک أَنْ ینْقَطِعَ بِهِمُ الْأَمَلُ\n\nعلت پیشی‌گرفتن بر مرگ این است:\nانسان دائم سلسله آرزوهایش را قصد می‌کند.\nبعد از رسیدن به آرزوها به سراغ دین و عمل می‌رود، اما زود رشته آرزوها قطع می‌شود. [یوشِک] دست از دنیا کوتاه شد؛ آرزو معنایی ندارد. قبل از تمام‌شدن دنیا و آرزوها اقدام و عمل کنید.\n\n♦️ وَیرْهِقُهُمُ الْأَجَلُ\n\nمرگ به‌زودی شما را کاملاً در بر می‌گیرد [یرْهِقُهُمُ] و هضم می‌کند.\n\n♦️ وَیسُدَّ عَنْهُمْ بَابَ التَّوْبَةِ\n\nوقتی اجل هم سررسید، درهای توبه بسته می‌شود.\nقبل از تمام‌شدن دنیا و واضح شدن سکرات مرگ، در توبه باز است؛ به حال خود فکری کنید، نگذارید مرگ بر شما سبقت بگیرد.\n\n♦️ فَقَدْ أَصْبَحْتُمْ فِی مِثْلِ مَا سَأَلَ إِلَیهِ الرَّجْعَةَ مَنْ کانَ قَبْلَکمْ\n\nذات انسان این‌طور است که معطل می‌کند، فرصت‌سوزی می‌کند؛ وقت که تمام شد دوباره طلب فرصت می‌کند.\nشما مانند این قصه‌ای نباشید که: عده‌ای مردند؛ بعد از خدا طلب رجعت کردند.\n«حَتَّیٰ إِذَا جَاءَ أَحَدَهُمُ الْمَوْتُ قَالَ رَبِّ ارْجِعُونِ لَعَلِّی أَعْمَلُ صَالِحًا فِیمَا تَرَکتُ قَالَ کلَّا - مؤمنون - ۹۹ و ۱۰۰»\nعده‌ای که مردند می‌گویند خدایا ما را برگردان تا آنچه از عمل صالح ترک کردیم را انجام بدهیم؛ در جواب می‌گوید: کلاً؛ هرگز.\nاین جمله را انسان می‌گوید؛ ولی کسی به آن ترتیب اثر نمی‌دهد. «إِنَّهَا کلِمَةٌ هُوَ قَائِلُهَا»\nالان که هستید، فرصت را مغتنم شمارید.\n\n♦️ وَأَنْتُمْ بَنُو سَبِیلٍ عَلَیٰ سَفَرٍ مِنْ دَارٍ لَیسَتْ بِدَارِکمْ\n\nشما در دنیا مسافرید؛ خانه از خود شما نیست. فرزندان راه هستید که طی طریق کنید. یک سفری را از یک‌خانه شروع کردید تا به مقصد برسید و خانه اجاره‌ای را باید پس بدهید. خانه، خانهٔ شما نیست.\n«حُبُّ الْوَطَنِ مِنَ الْإِیمَانِ» درست است که باید علقه به شهر و دیار و مرز جغرافیایی باشد؛ اما معنای سطح پایین است.\nبه قول شیخ بهایی «رحمة الله» وطن مصر و شام و عراق نیست؛ وطن اصلی معاد است.\n\n♦️ وَقَدْ أُوذِنْتُمْ مِنْهَا بِالِارْتِحَالِ\n\nآگاه باشید فردا روز که باید کوچ کنید، من به شما اعلام کردم [أُوذِنْتُمْ] و شما از این کوچ [ارتحال] باخبر شدید.\n\n♦️ وَأُمِرْتُمْ فِیهَا بِالزَّادِ\n\nنه‌تنها اعلام، بلکه امر هم شدید که برای مقصد خود، زاد و توشه جمع کنید.\nدر بهشت اگر نعمت فراوان است، مؤمنین از قبل فرستادند؛ لذا هر کس بر سفرهٔ گسترده خود میهمان است و استفاده می‌کند. قرار نیست برای کسی از جایی طعام بیاورند.\nمقایسه دنیا و آخرت:\n♦️ وَاعْلَمُوا أَنَّهُ لَیسَ بِهَذَا الْجِلْدِ الرَّقِیقِ صَبْرٌ عَلَی النَّارِ\nمی‌دانید پوست نازک‌بدن شما در مقابل یک خراش و یک ضربه طاقت ندارد.\nپوست‌نازک که هیچ صبر و تحملی ندارد و زود آسیب می‌بیند، چگونه در برابر آتش سهمگین جهنم طاقت می‌آورد؟!\nهر کدام بارها تجربه کردید و آگاهید چقدر ضعیف هستید. این پوست همان پوست است؛ چگونه عذاب را تحمل خواهید کرد؟!\n♦️ فَارْحَمُوا نُفُوسَکمْ فَإِنَّکمْ قَدْ جَرَّبْتُمُوهَا فِی مَصَائِبِ الدُّنْیا\nبه فکر خود باشید، به خود رحم کنید. [فَارْحَمُوا] بر اساس حب ذات که فطری است، انسان خود را دوست دارد و همه تلاش او برای این است که اوضاع خود را بهتر کند. همه را تجربه کردید [جَرَّبْتُمُوهَا]؛ پس بر اساس حب فطری بر خود رحم کنید که فردا آزار نبینید.\n♦️ أَفَرَأَیتُمْ جَزَعَ أَحَدِکمْ مِنَ الشَّوْکةِ تُصِیبُهُ\nآیا ندیدید کسی که خار [شَوْکة] به دست او رفته چگونه جزع‌وفزع می‌کند؟\n(حضرت خود ۲۵ سال خار بر چشم و استخوان در گلو صبر کردند که تصور آن هم سخت و سنگین است.)\n♦️ وَالْعَثْرَةِ تُدْمِیهِ وَالرَّمَضَاءِ تُحْرِقُهُ\nزمین‌خوردن [عَثْرَة] کسی را ندیدید که جراحت بردارد و زخمی شود [تُدْمِیه]؛ دادوفریاد دارد و از هوش می‌رود.\nحرکت در زمین پر حرارت و داغ [رَمَضَاء] آتش می‌گیرد و بی‌تابی می‌کند.\nاین سه مثال حضرت را همه چشیده و تجربه کرده‌ایم.\n♦️ فَکیفَ إِذَا کانَ بَینَ طَابَقَینِ مِنْ نَارٍ ضَجِعَ حَجَرٍ وَقَرِینَ شَیطَانٍ\nچگونه می‌تواند این پوست نحیف و نازک در دو طبق آتش [طَابَقَینِ] از بالا و پایین توان تحمل داشته باشد؟!\nاگر بر آن تحمل نیست پس بر خودتان رحم کنید و به داد خود برسید. درحالی‌که کناردست شما [ضَجِیع] سنگی که از شدت گرما مذاب شده وجود دارد و از همه بدتر، حقارت قرین شدن با شیطان است.\nآنهایی که گناه می‌کنید فکر می‌کنید جهنم یک مکان عادی و معمولی هست؟\nدر طرف مقابل، مؤمنین همنشین با انبیا و ملائک زوار هستند. وقتی تقوا رعایت نشود، همنشینی با شیطان، همان که در دنیا برای او «أَعُوذُ بِاللهِ» می‌گفت، مهیا می‌شود.\n♦️ أَعَلِمْتُمْ أَنَّ مَالِکا إِذَا غَضِبَ عَلَی النَّارِ حَطَّمَ بَعْضَهَا بِبَعْضٍ لِغَضَبِهِ\nوقتی مالک دوزخ بر آتش خشم گرفته و غضب می‌کند، آتش از هم می‌شکند، پرتاب می‌شود، بر روی‌هم می‌افتند و گُر می‌گیرد.\nفکر می‌کنید آتش بی‌شعور است، ملتفت نیست و نمی‌فهمد. با فریاد مالک دوزخ، آتش‌دست و پای خود گم می‌کند و از روی ترس به گوشه‌هایی پرتاب می‌شود.\nصدای خشن خازن دوزخ مساوی است با گُر گرفتن و سخت‌شدن آتش و جهنم به تلاطم می‌افتد.\n«یوْمَ نَقُولُ لِجَهَنَّمَ هَلِ امْتَلَأْتِ وَتَقُولُ هَلْ مِنْ مَزِیدٍ - ق - ۳۰»\nروزی که به جهنم می‌گوییم آیا پر شدی؟\nو جهنم می‌گوید آیا باز هم هست؛ و باز طلب می‌کند.\nآتش جهنم فهم دارد؛ یک موجود ذی‌شعور و فهیم است؛ یک آتش عادی نیست. آتش دنیا را خوش‌رفتاری یا خشم کنند، عکس‌العمل نشان نمی‌دهد؛ ولی جهنم می‌فهمد. کمااینکه در قیامت همه چیز می‌فهمند، کمااینکه در دنیا هم همه چیز می‌فهمند.\nکوه و آسمان و زمین می‌فهمند؛ اگر آسمان مطیع نبود عرش نمی‌شد. آسمان جسم جامد است؛ اما فهم متناسب با خود دارد.\nما سمیعیم و بصیریم و هشیم /\nبا شما نامحرمان ما خامشیم /\nبهشت و جهنم هدفمند هستند.\nذرات خاک و سنگ و … فهم دارند.\nپیرانی که عمر به بطالت و هوسرانی گذراندید، روزی جوان بودید و به خود وعدهٔ توبه در پیری دادید.\nاکنون پیری رسیده، در تمام سلول‌های وجود شما نفوذ کرده؛ پیری با چشم و گوش، مغز و جان شما مخلوط شده و توبه هم نکردید.\nپیرانی که چنین فرتوت شدند چگونه خواهند بود؟\nتحملشان با طوق آتشین بر گردن که گوشت را ذوب می‌کند و به استخوان می‌رسد؛ آیا تحمل خواهند کرد؟\n\n♦️ وَإِذَا زَجَرَهَا تَوَاثَّبَتْ بَینَ أَبْوَابِهَا جَزَلًا مِنْ زَجْرَتِهِ\n\nدومین عذاب آن لحظه‌ای است وقتی مالک فریاد می‌زند [زَجَرَهَا]؛ آتش به‌سوی درب جهنم پرتاب می‌شود، اما چیزی بیرون نمی‌رود. دوباره آتش بر روی آتش بر می‌گردد و همه به‌خاطر ترس است که از فریاد مأمور آتش دارد.\nآیا آمادهٔ چنین صحنه‌هایی هستید؟\nگناه کردید و قرار بود توبه کنید و نکردید….\nاللهم أعوذ بک من همزات الشیاطین","بخش سوم\nمتن:\nاَيُّهَا الْيَفَنُ الْكَبِيرُ الَّذِي قَدْ لَهَزَهُ الْقَتِيرُ، كَيْفَ أَنْتَ إِذَا الْتَحَمَتْ أَطْوَاقُ النَّارِ بِعِظَامِ الْأَعْنَاقِ وَ نَشِبَتِ الْجَوَامِعُ حَتَّى أَكَلَتْ لُحُومَ السَّوَاعِدِ. فَاللَّهَ اللَّهَ مَعْشَرَ الْعِبَادِ وَ أَنْتُمْ سَالِمُونَ فِي الصِّحَّةِ قَبْلَ السُّقْمِ وَ فِي الْفُسْحَةِ قَبْلَ الضِّيقِ، فَاسْعَوْا فِي فَكَاكِ رِقَابِكُمْ مِنْ قَبْلِ أَنْ تُغْلَقَ رَهَائِنُهَا. أَسْهِرُوا عُيُونَكُمْ وَ أَضْمِرُوا بُطُونَكُمْ وَ اسْتَعْمِلُوا أَقْدَامَكُمْ وَ أَنْفِقُوا أَمْوَالَكُمْ وَ خُذُوا مِنْ أَجْسَادِكُمْ فَجُودُوا بِهَا عَلَى أَنْفُسِكُمْ وَ لَا تَبْخَلُوا بِهَا عَنْهَا، فَقَدْ قَالَ اللَّهُ سُبْحَانَهُ «إِنْ تَنْصُرُوا اللَّهَ يَنْصُرْكُمْ وَ يُثَبِّتْ أَقْدامَكُمْ»، وَ قَالَ تَعَالَى «مَنْ ذَا الَّذِي يُقْرِضُ اللَّهَ قَرْضاً حَسَناً فَيُضاعِفَهُ لَهُ وَ لَهُ أَجْرٌ كَرِيمٌ»؛ فَلَمْ يَسْتَنْصِرْكُمْ مِنْ ذُلٍّ وَ لَمْ يَسْتَقْرِضْكُمْ مِنْ قُلٍّ، اسْتَنْصَرَكُمْ وَ لَهُ جُنُودُ السَّماواتِ وَ الْأَرْضِ وَ هُوَ الْعَزِيزُ الْحَكِيمُ، وَ اسْتَقْرَضَكُمْ وَ لَهُ خَزائِنُ السَّماواتِ وَ الْأَرْضِ وَ هُوَ الْغَنِيُّ الْحَمِيدُ، وَ إِنَّمَا أَرَادَ أَنْ يَبْلُوَكُمْ أَيُّكُمْ أَحْسَنُ عَمَلًا. فَبَادِرُوا بِأَعْمَالِكُمْ تَكُونُوا مَعَ جِيرَانِ اللَّهِ فِي دَارِهِ، رَافَقَ بِهِمْ رُسُلَهُ وَ أَزَارَهُمْ مَلَائِكَتَهُ، وَ أَكْرَمَ أَسْمَاعَهُمْ أَنْ تَسْمَعَ حَسِيسَ نَارٍ أَبَداً، وَ صَانَ أَجْسَادَهُمْ أَنْ تَلْقَى لُغُوباً وَ نَصَباً؛ ذلِكَ فَضْلُ اللَّهِ يُؤْتِيهِ مَنْ يَشاءُ وَ اللَّهُ ذُو الْفَضْلِ الْعَظِيمِ. أَقُولُ مَا تَسْمَعُونَ وَ اللَّهُ الْمُسْتَعانُ عَلَى نَفْسِي وَ أَنْفُسِكُمْ، وَ هُوَ حَسْبُنَا وَ نِعْمَ الْوَكِيل.\nترجمه:\nاى پير کهن سال! اى کسى که پيرى در سراسر وجودت نفوذ کرده! چگونه خواهى بود آن زمانى که طوقهاى آتشين به گردنها افکنده مى شود و غلهاى جامعه دست و گردن را به يکديگر مى بندد و چنان فشار مى دهد که گوشت هاى ساق دستها را مى خورد. خدا را خدا را! اى بندگان خدا! اکنون که سالم و تندرست هستيد و پيش از آنکه بيمار شويد و اکنون که در حال وسعت به سر مى بريد، پيش از آنکه در تنگناى زندگى قرار گيريد فرصت را غنيمت بشمريد و کوشش کنيد گردن خود را از زير بار مسئوليتها رها سازيد پيش از آنکه درهاى رهايى به روى شما بسته شود. چشمها را در دل شب بيدار داريد، شکمها را لاغر کنيد، گامها را بکار گيريد، اموال خود را انفاق کنيد و از جسم وتن خويش بکاهيد و بر جان و روان خود بيفزاييد و در اين کار بخل نورزيد. خداوند سبحان فرموده: «اگر خدا را يارى کنيد، شما را يارى مى کند و گامهايتان را استوار مى دارد» و نيز فرموده است: «کيست که به خداوند قرض نيکو دهد تا چند برابر به او عطا کند و براى چنين کسى پاداش والايى است». به يقين خدا به سبب ضعف و ناتوانى از شما يارى نطلبيده و قرض گرفتنش از شما (انفاق در راهش) به سبب کمبود نيست. او از شما يارى خواسته در حالى که لشکرهاى آسمانها و زمين از آن اوست و شکست ناپذير و حکيم است و (همچنين) از شما درخواست قرض کرده در حالى که گنجهاى آسمانها و زمين به او تعلق دارد و بى نياز و شايسته ستايش است. او خواسته است شما را بيازمايد که کدام يک نيکوکارتريد.\nحال که چنين است به اعمال نيک مبادرت ورزيد تا همنشين همسايگان خدا در سراى جاودان او باشيد. نزد کسانى که خداوند، پيامبران خود را رفيق آنها ساخته، فرشتگان خود را به ديدارشان فرستاده و حتى گوشهايشان را از اينکه صداى خفيف آتش دوزخ را بشنوند رهايى بخشيده و بدنهايشان را از ملاقات هرگونه رنج و ناراحتى مصون داشته است. اين فضل و رحمت الهى است که به هر کس بخواهد مى دهد و خداوند صاحب فضل عظيم است. من آنچه را مى شنويد مى گويم (و به شما اتمام حجت مى کنم) و خداوند را براى خود و شما به يارى مى طلبم و او کفايت کننده امور ما و بهترين حامى ماست.\nتفسیر:\nدر آخرین بخش از خطبه‌ای که به اذعان ابن ابی‌الحدید معتزلی، از مقایسه‌ی این خطبه با فصیح‌ترین کلمات عرب می‌توان نتیجه گرفت فصاحت و بلاغت چیست و نهج‌البلاغه چه جایگاه عظیمی دارد؟\n♦ «أَیهَا الْیفَنُ الْکبِیرُ الَّذِی قَدْ لَهَزَهُ الْقَتَیرُ»\n(در بخش قبل، حضرت به‌طورکلی همه‌ی انسان‌ها را مورد خطاب قرار دادند) در این بخش، به طور خاص، پیران و کسانی که سن و سالی از آن‌ها گذشته را خطاب قرار می‌دهند.\nای کسی که پیری در تمام وجود تو نفوذ کرده است [لَهَزَه]؛ در پیری، چشم کم‌سو می‌شود، دندان‌ها از کار می‌افتند و حواس انسان سر جای خود نیست؛ اعضا و جوارح سست و ضعیف می‌شوند و همه‌ی این‌ها از آفات پیری است [الْقَتَیر]؛ انسان پیری که ناراحتی تمام سر و پایش را فراگرفته است.\n♦ «کیفَ أَنْتَ إِذَا الْتَحَمَتْ أَطْوَاقُ النَّارِ بِعِظَامِ الْأَعْنَاقِ»\nچگونه خواهی بود لحظه‌ای که طوقی از آتش به استخوان گردنت برسد به استخوان گردنت برسد؟\n♦ «وَنَشِبَتِ اْ لُحُومَ السَّوَاعِدِ»\nو چگونه خواهی بود زمانی که غل‌وزنجیر [الْجَوَامِع] از گردن و دست‌هایت آویزان باشد [نَشِبَتْ]، آن‌گونه که این غل‌وزنجیر گوشت دستت را بخورد و آرام‌آرام آب کند [أَکلَتْ]؛ حالت چگونه خواهد بود؟\nحضرت دو عذاب را ذکر فرمودند که تفکر در مورد آن‌ها حال انسان را دگرگون می‌کند. عذاب اول، عذاب پیران است؛ زمانی که طوقی از آتش دور گردن آن‌هاست و آتش گوشت گردن را ذوب می‌کند تا به استخوان گردن برسد.\nچگونه است آتشی که پوست و گوشت را ذوب کند و به استخوان برسد و استخوان را بسوزاند؟ آیا در مقابل این عذاب تحمل می‌کنید؟\nعذاب دوم؛ منظور از «جوامع» در اصطلاح عربی، غل و زنجیری است به همین نام که در روضه‌ی کربلا و در مورد امام سجاد نیز آمده است («العُنُقُ الْجَامِعَة»: سلام بر تو، ای امام مظلومی که در گردنت غل‌وزنجیر جامعه بود). در مورد غل‌وزنجیر جامعه، تفاسیر گوناگونی وجود دارد.\nبرخی گفته‌اند چوبی است که دو طرف گردن و دو طرف دست‌ها را می‌گیرد؛ دست رو به آسمان و گردن داخل آن است، و چون دست و گردن را به هم می‌پیوندد، آن را جامعه می‌نامند.\nدر برخی نقل‌های دیگر، از نظر تاریخی، منظور از غل‌وزنجیر جامعه، زنجیری است که از گردن به دست‌ها و از دست‌ها به پا بسته می‌شود؛ یعنی سرتاپای انسان در زنجیر است.\nبرخی می‌گویند منظور از جامعه، همان است که در مورد امام سجاد آمده («مَغْلُولَةٌ یدُهُ إِلَی عُنُقِهِ»): ای کسی که دستش به گردنش بسته شده بود.\nبرخی نیز ذیل آیه («یعْرَفُ الْمُجْرِمُونَ بِسِیمَاهُمْ فَیؤْخَذُ بِالنَّوَاصِی وَالْأَقْدَامِ») گفته‌اند موی سر و پای گناهکار هم‌زمان گرفته می‌شود؛ یعنی غل و زنجیری به دست‌وپای گناهکاران بسته می‌شود و با خواری و ذلت به جهنم افکنده می‌شوند.\nغل‌وزنجیر جوامع، نسبت به غل‌وزنجیر عادی، شرایط سخت‌تری دارد. حضرت فرمود جهنم ذی‌شعور است و گناهکاران را می‌گیرد، و در اینجا فرمود عذابش نیز دردناک است.\n♦ «فَاللهَ اللهَ مَعْشَرَ الْعِبَادِ! وَأَنْتُمْ سَالِمُونَ فِی الصِّحَّةِ قَبْلَ السُّقْمِ»\nخدا را، خدا را، ای مردم! تا وقتی سالم هستید و بیماری [السُّقْم] به سراغتان نیامده، کاری کنید؛ الان فرصت کار است، زیرا انسان پیر و بیمار، عبادتش نیز سخت است.\n♦ «وَفِی الْفُسْحَةِ قَبْلَ الضِّیقِ»\nالان که وسعت زمان [الْفُسْحَة] دارید و وسعت زندگی دارید و در تنگنا [الضِّیق] نیستید، کاری کنید و آخرت خود را آباد کنید.\nشما را به خدا قسم می‌دهم، ای زنان، ای مردان، ای انسان‌ها؛ امروز که حالتان خوب است و بیمار نیستید، فرصت دارید و وسعت دارید،\nپیش از آنکه شما را در تنگنای قبر بگذارند،\nاز این دو نعمت - سلامت و وسعت - استفاده کنید؛ تا شرایط جسمانی‌تان خوب است و آمادگی دارید، این دو نعمت الهی را به کار گیرید و در آزادکردن گردن‌های خود بکوشید.\n♦ «فَاسْعَوْا فِی فَکاک رِقَابِکمْ مِنْ قَبْلِ أَنْ تُغْلَقَ رَهَائِنُهَا»\nبا تمام قدرت تلاش کنید [فَاسْعَوْا] تا گردن خود را آزاد کنید؛ ای مردم، به تکالیفی مکلف هستید [فَکاک رِقَابِکمْ]؛ خود را بری‌الذمه کنید، پیش از آنکه گردنتان بسته شود [تُغْلَقَ]، کاری کنید تا آزاد شود.\nهمه‌ی ما در گرو هستیم؛ خدا ما را گرو گرفته است. برخلاف دنیا - که اگر پولی در جیب نداشته باشید، ساعت یا انگشترتان را گرو می‌گذارید - خدا خودِ ما را در گرو گرفته و فرموده است یا با اعمال صالح از این گرو آزاد می‌شوید، یا در بند و گرفتار باقی می‌مانید.\nبدون عمل صالح و انجام تکالیف، به حریت و آزادی نمی‌رسیم. وقتی مرگ فرارسد، دیگر نمی‌توانیم خود را که در رهن هستیم آزاد کنیم؛ پس چه باید کرد؟ به طور مصداقی و خاص، برای ما بگویید.\nپنج توصیه که بهتر از سایر اعمال است، با استفاده از دو نعمتِ سلامت و فرصت:\n♦ «أَسْهِرُوا عُیونَکمْ»\n۱- در شب‌ها چشمان خود را بیدار نگه دارید [أَسْهِرُوا]. «فَتَهَجَّدْ بِهِ نَافِلَةً لَک أَنْ یبْعَثَک رَبُّک مَقَاماً مَحْمُوداً» (اسرا، ۷۹).\nروایتی در «مَنْ لا یحْضُرُهُ الْفَقِیه»، جلد ۱، صفحه‌ی ۴۷۵، از امام باقر آمده، در باب وقت نماز شب که وقتی به نیمه‌شب شرعی رسیدید، وقت نماز شب شروع می‌شود؛ یعنی از اذان مغرب تا اذان صبح را تقسیم بر دو کنید. می‌توان نماز شب خواند: «وَمَنْ صَلَّی تُسُعَ لَیلِهِ أَعْطَاهُ اللهُ عَشْرَ دَعَوَاتٍ مُسْتَجَابَاتٍ وَأَعْطَاهُ اللهُ کتَابَهُ بِیمِینِهِ». اگر کسی یک‌نُهم شب را بیدار باشد، خدا ده دعای مستجاب به او می‌دهد و در روز قیامت او را روسفید می‌کند. نماز شب، یعنی عبادتی که در نیمه‌شب در ارتباط با خداست؛ برای مؤمنین دعا کنید؛ این خودسازی و مدارا با مؤمنین است.\n♦ «وَأَضْمِرُوا بُطُونَکمْ»\n۲- شکم‌ها و بدن خود را فربه نکنید [أَضْمِرُوا]؛ اهل روزه و مدارا باشید و با روزه، خود را لاغر کنید.\n♦ «وَاسْتَعْمِلُوا أَقْدَامَکمْ»\n۳- در راه رسیدن به خیر، قدم‌های خود را به کار گیرید و در مسیر رضای خدا و رضایت رسول خدا گام بردارید؛ پا روی نفس خود بگذارید.\n♦ «وَأَنْفِقُوا أَمْوَالَکمْ»\n۴- فقط برای خود جمع نکنید؛ دیگران را هم ببینید و انفاق کنید؛ اموال خود را ببخشید.\n♦ «وَخُذُوا مِنْ أَجْسَادِکمْ»\n۵- از جسم خود بکاهید تا به روح خود بیفزایید؛ در تقابل جسم و روح، جود و بخشش کنید.\n♦ «فَجُودُوا بِهَا عَلَی أَنْفُسِکمْ»\n۶- آنچه از جسم کاسته‌اید را به جان خود بیفزایید. وجه مشترک ما و حیوانات، جسم است. عموماً به جسم می‌پردازیم و کوچک‌ترین درد آن را درمان می‌کنیم، اما در مورد روح و جان چنین نمی‌کنیم. مقداری از جسم خود بکاهید و این افزوده را به جانتان ببخشید. ریاضت شرعی یعنی به جایی برسیم که به اختیار خود پرخوری نکنیم؛ باید زهد را برگزینیم و به‌سوی تجمل نرویم.\nجسم خود را برای روح ایثار کنید.\nاصل این است که جسم رو به فرسایش است و خسته و ناتوان می‌شود؛ اگر شما جسم خود را در این راه مصرف نکنید، روزگار آن را تجزیه خواهد کرد.\n♦ «وَلَا تَبْخَلُوا بِهَا عَنْهَا»\n۷- مبادا بخل ورزید؛ از نفس به جسم بخل نورزید، از این‌که برای نفس خود اسراف کنید.\n♦ «فَقَدْ قَالَ اللهُ سُبْحَانَهُ: إِنْ تَنْصُرُوا اللهَ ینْصُرْکمْ وَیثَبِّتْ أَقْدَامَکمْ»\nدر شرح عبادات، حضرت ما را به قرآن ارجاع می‌دهد: اگر خدا را نصرت کنید، خدا نیز قطعاً شما را نصرت می‌دهد و ثابت‌قدم می‌کند. «إِنْ» شرط است؛ اگر خدا را یاری کنید، حتماً یاری‌تان می‌دهد و حتماً ثابت‌قدمتان می‌کند؛ همان قدمی که در مسیر شهدا و اهل‌بیت رفت، ثابت می‌ماند و در شبهات نمی‌لرزد، مانند درختی ریشه‌دار که هیچ تندبادی آن را ریشه‌کن نمی‌کند.\n♦ «وَقَالَ تَعَالَی: مَنْ ذَا الَّذِی یقْرِضُ اللهَ قَرْضاً حَسَناً فَیضَاعِفَهُ لَهُ وَلَهُ أَجْرٌ کرِیمٌ»\nخدای تعالی فرمود کدام یک از شما حاضر است به خدا قرض بدهد؟ هر کس به خدا قرض بدهد، خدا نیز چندبرابر به او برمی‌گرداند و هم دنیایش تأمین می‌شود و هم در آخرت اجر کریم دارد.\nکرامت مربوط به آن دنیاست؛ کدام یک از شما به خدا قرض می‌دهد؟ این برمی‌گردد به جمله‌ی «وَأَنْفِقُوا أَمْوَالَکمْ»: اموالتان را در راه خدا بدهید. هر کس این کار را بکند، باخدا معامله می‌کند؛ مگر خدا فقیر است که به او قرض بدهیم؟\n♦ «فَلَمْ یسْتَنْصِرْکمْ مِنْ ذُلٍّ وَلَمْ یسْتَقْرِضْکمْ مِنْ قُلٍّ»\nخدا از شما طلب نصرت نکرده است، چون ذلیل باشد - انسان گاهی دست نیاز به کسی دراز می‌کند - و اگر خدا از شما طلب قرض کرده، به‌خاطر کمبود و قِلَّت نیست. پس چرا از ما یاری خواسته است؟ حضرت پاسخ داده‌اند:\n♦ «اسْتَنْصَرَکمْ وَلَهُ جُنُودُ السَّمَاوَاتِ وَالْأَرْضِ وَهُوَ الْعَزِیزُ الْحَکیمُ»\nاز شما طلب نصرت کرده، درحالی‌که تمام لشکریان آسمان و زمین از آنِ او و در فرمان او هستند؛ تمام آسمان و زمین در قبضه‌ی قدرت اوست و او نفوذناپذیر [الْعَزِیز] و حکیم است.\n♦ «وَاسْتَقْرَضَکمْ وَلَهُ خَزَائِنُ السَّمَاوَاتِ وَالْأَرْضِ وَهُوَ الْغَنِی الْحَمِیدُ»\nاز شما طلب قرض کرده، درحالی‌که تمام خزائن آسمان‌ها و زمین از آنِ اوست و او غنیِ بالذات است.\n♦ «وَإِنَّمَا أَرَادَ أَنْ یبْلُوَکمْ أَیکمْ أَحْسَنُ عَمَلاً»\nخدا خواست که او را کمک کنید و به او قرض بدهید تا شما را بیازماید؛ همه‌ی این‌ها به‌خاطر آزمایش شماست، تا میزان و عیارتان مشخص شود.\nدر آیه‌ی ۴ سوره‌ی محمد آمده: «وَلَوْ یشَاءُ اللهُ لَانْتَصَرَ مِنْهُمْ وَلَکنْ لِیبْلُوَ بَعْضَکمْ بِبَعْضٍ». اگر خدا می‌خواست، می‌توانست همه‌ی گرفتاری‌ها را حل کند، ولی از ما طلب کرد تا ما را بیازماید؛ برخی را به‌واسطه‌ی دیگری آزمایش کند. عبادت و طاعت ما از سرِ نیاز خدا نیست؛ خدا به هیچ‌کس و هیچ‌چیز محتاج نیست؛ این برای بالابردن مقام خودِ شماست.\n♦ «فَبَادِرُوا بِأَعْمَالِکمْ تَکونُوا مَعَ جِیرَانِ اللهِ فِی دَارِهِ»\nدر اعمال صالح با تمام توان مبادرت ورزید (بشتابید). اگر مبادرت به اعمال صالح کنید، در خانه‌ی خدا با همسایگان [جِیرَان] خدا همسایه می‌شوید. در بخش قبل از خطبه نیز «جِیرَانِ اللهِ» آمده است؛ یکی از ویژگی‌های مؤمنین واقعی این است که همسایه‌ی خدا می‌شوند؛ همسایگی خدا در گرو قلب ماست؛ قیامت تجسم اعمال ماست.\nویژگی همسایگی بهشت چیست؟\n♦ «رَافَقَ بِهِمْ رُسُلَهُ وَأَزَارَهُمْ مَلَائِکتُهُ وَأَکرَمَ أَسْمَاعَهُمْ أَنْ تَسْمَعَ حَسِیسَ نَارٍ أَبَداً»\n۱- انبیاء با آن‌ها رفیق می‌شوند.\n۲- ملائکه به زیارت آن‌ها می‌روند (منظور مردم عادی است).\n۳- خدا کاری می‌کند که کوچک‌ترین صدای آتش به گوششان نرسد؛ یکی از عذاب‌های جهنم، صدای آتش است؛ خدا کاری می‌کند که همسایگانش صدای آتش را نشنوند.\n♦ «وَصَانَ أَجْسَادَهُمْ أَنْ تَلْقَی لُغُوباً وَنَصَباً؛ ذَلِک فَضْلُ اللهِ یؤْتِیهِ مَنْ یشَاءُ وَاللهُ ذُو الْفَضْلِ الْعَظِیمِ»\n۴- و خدا اجساد این «جیران الله» را صیانت می‌کند [صَانَ] از آنکه با خستگی روحی [لُغُوب] و خستگی جسمی [نَصَب] روبه‌رو شوند.\nیکی از برکات همسایگان خدا این است که نه خستگی جسمی در آن‌ها راه دارد و نه خستگی روحی.\nروح آن‌ها لذت می‌برد؛ نه جسمشان آزار می‌بیند و نه سکونی در آن‌ها هست، چون سکون باعث خستگی است. در بهشت، رشد و تکامل جاری است؛ این فضل خداست که عده‌ای همسایه‌ی خدا باشند.\n♦ «أَقُولُ مَا تَسْمَعُونَ وَاللهُ الْمُسْتَعَانُ عَلَی نَفْسِی وَأَنْفُسِکمْ وَهُوَ حَسْبُنَا وَنِعْمَ الْوَکیلُ»\nاین جمله دو معنا دارد.\nمعنای اول: آنچه را که می‌شنوید می‌گویم؛ یعنی من سخنان را به شما گفتم و حجت را بر شما تمام کردم؛ اختیار عمل با خودتان است؛ وظیفه‌ی من اتمام حجت است.\nمعنای دوم: یک چیزی می‌گویم و شما یک چیز دیگر می‌شنوید؛ من از بهشت و عجایب و نعمت‌های آن، و فضایل خدا نسبت به بهشتیان، چه بگویم؟ همین‌طور در مورد جهنم؛ جهنم نیز مانند بهشت توصیف‌شدنی نیست.\nامیرالمؤمنین رائد است؛ حضرت می‌فرماید من از آن طرف آمده‌ام و همه چیز را به شما می‌گویم، بشنوید. از خدا طلب یاری می‌کنم، هم بر نفس خودم و هم بر نفس شما، و خدا کفایتمان می‌کند و او بهترین وکیل است.\nیعنی کار خود را به خدا بسپار؛ او به بهترین نحو کفایت می‌کند؛ همه‌کاره‌ی عالم خداست و به بهترین نحو مشکل را حل می‌کند.\nاز خدا طلب یاری می‌کنم، هم بر نفس خودم و هم بر نفس شما؛ نفوس فراوان است، لذا در هر مرحله‌ای باید از خدا طلب یاری کرد. گرفتاری ما با نفس اماره است که امر به بدی می‌کند؛ باید استعانت جست، چون به‌تنهایی حریف نفس و شیطان نمی‌شویم؛ راه استعانت از خداست و خدا دست ما را می‌گیرد.\nاللَّهُمَّ عَجِّلْ لِوَلِیک الْفَرَجَ\nوَاجْعَلْ عَوَاقِبَ أُمُورِنَا خَیراً"]});
